cols=['sample_id','tic','sample_stratum','physical_verdict','full_review_completion','novelty_status','period_days','period_error_days','primary_epoch_btjd','depth_ppt','limitations','next_check','report']
rows=[]
for q in csv.DictReader((B/'queue.csv').open(encoding='utf8')):
    sid=q['sample_id'];tic=q['tic'];d=DATA[sid];D=B/tic
    ctx=json.loads((D/'lead-context.json').read_text());flags=json.loads((D/'lead-flag-diagnostics.json').read_text())
    assert len(ctx['sectors'])==int(q['usable_files'])
    rep=f"""# {sid} — TIC {tic}\n\n**Physical verdict:** {d['v']}. **EB novelty:** {d['novelty']}. **Review completion:** COMPLETE.\n\n## Raw evidence\n\n{d['finding']}\n\n## Timing, physics and source\n\n{d['physics']}\n\n## Limits and next check\n\n{d['limits']}\n\n{d['next']}\n\n## Reproduction\n\n`lead_context.py` verifies source-packet, bulk-result and FITS SHA-256 values, then plots raw SAP for all {len(ctx['sectors'])} cached sectors. `lead-context.json` and `lead-local-series.json` retain numeric time/flux, actual quality-zero coverage and gaps. `lead-flag-diagnostics.json` records core endpoints for {len(flags)} selected dip windows. `lead-alternate.png/json` compare reductions of the same photons. `lead-gaia-geometry.json` records source-specific orbital elements where used. `lead-neighbors.json` records MAST TIC cone data for Q061/Q068; `lead-timing.json` and `lead-extended-timing.json` contain measured eclipse centers. `lead-halfphase.json` records revised-clock shorter-alias checks; `lead-sector-availability.json` documents the Q062 availability discrepancy. The independent helper audit supplies pixel and WCS evidence. Screening centers are predictions, not measured eclipse times.\n"""
    (D/'REPORT.md').write_text(rep,encoding='utf8')
    rows.append(dict(sample_id=sid,tic=tic,sample_stratum=q['sample_stratum'],physical_verdict=d['v'],full_review_completion='COMPLETE',novelty_status=d['novelty'],period_days=d['period'],period_error_days='',primary_epoch_btjd=d['epoch'],depth_ppt=d['depth'],limitations=d['limits'],next_check=d['next'],report=str((D/'REPORT.md').resolve())))
with (B/'RESULTS.csv').open('w',encoding='utf8',newline='') as f:
    w=csv.DictWriter(f,fieldnames=cols);w.writeheader();w.writerows(rows)
print({r['sample_id']:r['physical_verdict'] for r in rows})
